-- GENERE par generer_armes_jet_referentiel.cjs --sql depuis les déclarations existantes.
BEGIN;
CREATE TABLE IF NOT EXISTS public.armes_jets_referentiel(pays text,ville text,batiment text,piece text,arme text,data jsonb NOT NULL,PRIMARY KEY(pays,ville,batiment,piece,arme));
ALTER TABLE public.armes_jets_referentiel ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.armes_jets_referentiel FROM PUBLIC,anon,authenticated,service_role;
DO $r$ DECLARE divergent boolean;BEGIN
 WITH attendu(pays,ville,batiment,piece,arme,data) AS(VALUES ('republic','capitale','armurerie','magasin','couteau','{"objet":{"type":"arme","sousType":"blanche","name":"Couteau de poche","icon":"ti-tools-kitchen-2","desc":"Légal pour la chasse. Roger ne demande pas à qui.","legal":false,"bonus":{"stat":"VOL","val":5},"imageUrl":"images/arme-couteau-republic.webp"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
