('republic','ville_a','chasse-peche-psm','boutique','revolver','{"objet":{"type":"arme","sousType":"poing","name":"Fusil sous-marin","icon":"ti-crosshair","desc":"Harpon professionnel à sandow, moulinet grande capacité. Idéal pour la chasse sous-marine.","legal":false,"bonus":{"stat":"PER","val":8},"imageUrl":"images/armurerie-port-sainte-marie-fusil-harpon.webp"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('republic','ville_a','chasse-peche-psm','boutique','carabine_chasse','{"objet":{"type":"arme","sousType":"carabine","name":"Carabine de chasse","icon":"ti-target-arrow","desc":"Modèle Saint-Marian, mécanisme à verrou, crosse en bois massif. Idéale pour la chasse côtière.","legal":false,"bonus":{"stat":"PER","val":15},"imageUrl":"images/armurerie-port-sainte-marie-carabine.webp"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
