('republic','ville_b','armurerie','magasin','revolver','{"objet":{"type":"arme","sousType":"poing","name":"Revolver .38","icon":"ti-crosshair","desc":"Fiable, discret, classique. Trois balles suffisent généralement.","legal":false,"bonus":{"stat":"PER","val":8},"imageUrl":"images/arme-fusil-republic.webp"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('republic','ville_b','armurerie','magasin','carabine_chasse','{"objet":{"type":"arme","sousType":"carabine","name":"Carabine de chasse","icon":"ti-target-arrow","desc":"Pour le gibier. Gros gibier.","legal":false,"bonus":{"stat":"PER","val":15},"imageUrl":"images/arme-revolver-republic.webp"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('narco','capitale','armurerie','magasin','machette','{"objet":{"type":"arme","sousType":"blanche","name":"Machette","icon":"ti-tools-kitchen-2","desc":"L''outil universel. Multi-usages.","legal":false,"bonus":{"stat":"VOL","val":5},"imageUrl":"images/arme-machette-narco.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('narco','capitale','armurerie','magasin','desert_eagle','{"objet":{"type":"arme","sousType":"poing","name":"Desert Eagle","icon":"ti-crosshair","desc":"El Don lui-même en possède trois.","legal":false,"bonus":{"stat":"PER","val":10},"imageUrl":"images/arme-deserteagle-narco.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('narco','capitale','armurerie','magasin','ak47','{"objet":{"type":"arme","sousType":"carabine","name":"AK-47","icon":"ti-target-arrow","desc":"Origine : inconnue. État : parfait.","legal":false,"bonus":{"stat":"PER","val":18},"imageUrl":"images/arme-ak47-narco.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('soviet','capitale','armurerie','magasin','baionnette','{"objet":{"type":"arme","sousType":"blanche","name":"Baïonnette","icon":"ti-tools-kitchen-2","desc":"Propriété du Peuple. Empruntée indéfiniment.","legal":false,"bonus":{"stat":"VOL","val":5},"imageUrl":"images/arme-baionnette-soviet.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('soviet','capitale','armurerie','magasin','makarov','{"objet":{"type":"arme","sousType":"poing","name":"Makarov","icon":"ti-crosshair","desc":"Standard réglementaire. Camarade Kalachnikov détourne le regard.","legal":false,"bonus":{"stat":"PER","val":8},"imageUrl":"images/arme-makarov-soviet.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('soviet','capitale','armurerie','magasin','kalachnikov','{"objet":{"type":"arme","sousType":"carabine","name":"Kalachnikov","icon":"ti-target-arrow","desc":"Pour la défense de la Patrie. Usage personnel toléré.","legal":false,"bonus":{"stat":"PER","val":16},"imageUrl":"images/arme-kalachnikov-soviet.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('khalija','capitale','armurerie','magasin','jambiya','{"objet":{"type":"arme","sousType":"blanche","name":"Jambiya","icon":"ti-tools-kitchen-2","desc":"Lame recourbée, tradition millénaire. Hassan l''a aiguisée ce matin.","legal":false,"bonus":{"stat":"VOL","val":6},"imageUrl":"images/arme-jambiya-khalija.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('khalija','capitale','armurerie','magasin','pistolet_dore','{"objet":{"type":"arme","sousType":"poing","name":"Pistolet doré","icon":"ti-crosshair","desc":"Serti de nacre. L''élégance n''exclut pas l''efficacité.","legal":false,"bonus":{"stat":"PER","val":9},"imageUrl":"images/arme-pistolet-khalija.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb),
('khalija','capitale','armurerie','magasin','carabine_precision','{"objet":{"type":"arme","sousType":"carabine","name":"Carabine de précision","icon":"ti-target-arrow","desc":"Pour la chasse au faucon. Très grands faucons.","legal":false,"bonus":{"stat":"PER","val":17},"imageUrl":"images/arme-fusil-khalija.png"},"bonusCarrieres":{"criminal_c":15,"intel":15,"escort":15,"magistrat":-10,"officer":-10,"clergy":-10,"doctor":-10}}'::jsonb)),inseres AS(INSERT INTO public.armes_jets_referentiel SELECT * FROM attendu ON CONFLICT DO NOTHING RETURNING *),effectif AS(SELECT * FROM public.armes_jets_referentiel UNION ALL SELECT * FROM inseres) SELECT EXISTS(SELECT 1 FROM attendu a FULL JOIN effectif e USING(pays,ville,batiment,piece,arme) WHERE a.data IS DISTINCT FROM e.data) INTO divergent;
 IF divergent THEN RAISE EXCEPTION 'referentiel_armes_jets_divergent';END IF;
END;$r$;
COMMIT;
